/*
 * prog54_topo_sort.c
 *
 * Re‑implementation of the original program whose behaviour was
 * recovered from the obfuscated binary.  The program expects two
 * command‑line arguments:
 *
 *   prog54_topo_sort  V  E
 *
 *   V – number of vertices (0 … 7)
 *   E – number of directed edges (0 … 7)
 *
 * After the arguments the program reads exactly E pairs of integers
 * from standard input, each pair representing a directed edge
 *   u v
 * with 0 ≤ u , v < V.
 *
 * If any of the above conditions are violated the program prints
 *   INVALID_INPUT\n
 * and exits with status 1.
 *
 * Otherwise it performs a Kahn topological sort.  If the graph
 * contains a cycle the program prints
 *   CYCLE\n
 * and exits with status 1.
 *
 * If the graph is acyclic the program prints the vertices in one
 * possible topological order, separated by a single space, followed
 * by a newline, and exits with status 0.
 *
 * The original binary was limited to at most 8 vertices and 8 edges,
 * therefore the implementation uses fixed‑size arrays of length 8.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8          /* maximum number of vertices */
#define MAXE 8          /* maximum number of edges */

int main(int argc, char *argv[])
{
    long v_long, e_long;
    int V, E;
    int adj[MAXV][MAXV] = {0};   /* adjacency matrix */
    int indeg[MAXV] = {0};       /* indegree of each vertex */
    int done[MAXV] = {0};        /* marks vertices already output */
    int order[MAXV];             /* resulting topological order */
    int order_len = 0;

    /* ---------- argument handling ---------- */
    if (argc != 3) {
        puts("INVALID_INPUT");
        return 1;
    }

    v_long = strtol(argv[1], NULL, 10);
    e_long = strtol(argv[2], NULL, 10);

    if (v_long < 0 || v_long >= MAXV || e_long < 0 || e_long >= MAXE) {
        puts("INVALID_INPUT");
        return 1;
    }

    V = (int)v_long;
    E = (int)e_long;

    /* ---------- read edges ---------- */
    for (int i = 0; i < E; ++i) {
        int u, w;
        if (scanf("%d %d", &u, &w) != 2) {
            puts("INVALID_INPUT");
            return 1;
        }
        if (u < 0 || u >= V || w < 0 || w >= V) {
            puts("INVALID_INPUT");
            return 1;
        }
        /* store edge u -> w */
        if (!adj[u][w]) {               /* ignore duplicate edges */
            adj[u][w] = 1;
            indeg[w] += 1;
        }
    }

    /* ---------- Kahn's topological sort ---------- */
    int queue[MAXV];
    int qhead = 0, qtail = 0;
    for (int i = 0; i < V; ++i) {
        if (indeg[i] == 0) {
            queue[qtail++] = i;
        }
    }

    while (qhead < qtail) {
        int v = queue[qhead++];
        done[v] = 1;
        order[order_len++] = v;

        for (int w = 0; w < V; ++w) {
            if (adj[v][w]) {
                indeg[w]--;
                if (indeg[w] == 0) {
                    queue[qtail++] = w;
                }
            }
        }
    }

    /* ---------- check for cycles ---------- */
    if (order_len != V) {
        puts("CYCLE");
        return 1;
    }

    /* ---------- output order ---------- */
    for (int i = 0; i < order_len; ++i) {
        if (i) putchar(' ');
        printf("%d", order[i]);
    }
    putchar('\n');
    return 0;
}
